const SOURCES=[{label:'FDA: what an IND contains',url:'https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-B/section-312.23'},{label:'FDA: purpose of IND review',url:'https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-312/subpart-B/section-312.22'},{label:'ICH S9: advanced cancer with limited treatment options',url:'https://www.fda.gov/media/73161/download'},{label:'FDA: Phase 1 small-molecule CMC clarifications',url:'https://www.fda.gov/media/193163/download?attachment='},{label:'FDA: clinical protocols',url:'https://www.fda.gov/drugs/investigational-new-drug-ind-application/ind-applications-clinical-investigations-clinical-protocols'},{label:'FDA: exposure–response',url:'https://www.fda.gov/media/71277/download'}];
const STREAMS=[{id:'biology',code:'01 / BIOLOGY',name:'Pharmacology',sub:'Activity & exposure',title:'What does the drug do, and at what exposure?',text:'Mechanism and efficacy studies provide a biological rationale. PK (pharmacokinetics) describes exposure over time; PD (pharmacodynamics) measures biological effects. Linking them helps interpret the administered dose.'},{id:'tox',code:'02 / SAFETY',name:'Toxicology',sub:'Hazards & conditions',title:'What could go wrong in the proposed study?',text:'Characterize affected organs, severity, exposure, timing, and potential recovery. Interpret findings in the context of species relevance and the planned human regimen.'},{id:'cmc',code:'03 / QUALITY',name:'CMC',sub:'Material & control',title:'What exactly will people receive?',text:'Phase-appropriate chemistry, manufacturing, and controls describe the drug substance and product, how they are made, tested, and stored, and whether the material supports the proposed use.'},{id:'clinical',code:'04 / PEOPLE',name:'Clinical plan',sub:'Learn with safeguards',title:'How will this study generate interpretable evidence?',text:'Define participants, dosing, measurements, and safety rules. The proposed study determines what support is needed from the other workstreams.'}];
const QUESTIONS={
 map:{title:'A stronger result. A narrower claim.',prompt:'A candidate produces convincing tumor growth inhibition in mice. What does that result most directly support?',options:[['A biological rationale to investigate the candidate further.','Yes. Retain the activity result and define its limits. It does not answer product quality, human risk, or clinical benefit by itself.',true],['That the candidate is ready to dose in humans.','Activity is one part of the argument. Exposure, safety, product quality, and the proposed study still need support.',false],['That the same dose will work in humans.','A dose in one species does not establish human exposure, target effects, or a useful human regimen.',false]]},
 model:{title:'Keep the result. Repair the inference.',prompt:'In the original setting, the mouse intestinal pathway was not suppressed. Which conclusion is supported?',options:[['The normal human intestine will be spared.','The study did not test normal human intestine or the relevant pathway inhibition in the mouse intestine.',false],['Human intestinal injury is certain.','A mechanistic concern is not proof of injury. The risk remains unresolved; investigate it with relevant evidence.',false],['Tumor activity is supported; human intestinal risk remains unresolved.','Yes. Keep the useful observation and limit the extrapolation. The next experiment should address the missing biological condition.',true]]},
 exposure:{title:'Same dose. New formulation.',prompt:'A new formulation increases exposure at the same administered dose. What is the useful next step?',options:[['Keep the previous safety interpretation because the dose is unchanged.','The administered amount stayed the same; achieved exposure did not. Dose alone cannot establish that the prior interpretation still applies.',false],['Compare new exposure and product differences with the existing safety evidence.','Yes. Review the exposure, schedule, findings, and material represented by the existing studies. Then assess whether additional support is needed.',true],['Automatically repeat every toxicology study.','A change calls for an assessment of its implications. It does not automatically require repeating every study.',false]]}
};
const BRIEF_CONTENT={
 cmc:{title:'The molecule becomes a product.',lede:'Chemistry, manufacturing, and controls (CMC) connect the chemical entity to the material used in a study.',cards:[['Drug substance','The active pharmaceutical ingredient (API): its identity, manufacture, characterization, and relevant impurities.'],['Drug product','The formulated medicine people receive: composition, manufacture, tests, packaging, and stability.'],['Evidence of control','Specifications define tests, methods, and acceptance criteria. A certificate of analysis records a batch’s results; release also involves the applicable quality review.']],question:'Why a discovery scientist should care',answer:'If the clinical formulation or process changes, assess what changed in the material and exposure. The biological evidence must remain interpretable for the proposed product and use.',lens:'Think of sample provenance and assay controls at the scale of an administered product. A chemical name alone is not a complete description of the material.',source:3,terms:'GMP = good manufacturing practice. Phase 1 controls are appropriate to the development stage; an initial IND does not need a finished commercial manufacturing package.'},
 clinical:{title:'The study is part of the argument.',lede:'A clinical protocol specifies what will happen, what will be measured, and how decisions will be made.',cards:[['Question + participants','Define the study objectives, endpoints, and eligibility. Phase 1 does not always mean healthy volunteers.'],['Dose + decisions','Justify the starting dose, schedule, escalation, interruptions, and stopping rules using the available evidence and uncertainties.'],['Measurements + oversight','Plan safety monitoring, PK, relevant PD, follow-up, and who reviews emerging data. The design should produce interpretable information.']],question:'What changes when the schedule changes?',answer:'A longer or different exposure pattern may change the support needed from nonclinical studies. The clinical plan and evidence package should inform each other.',lens:'A protocol is a prospective experiment with prespecified decisions. A measured biomarker effect does not automatically demonstrate clinical benefit.',source:4,terms:'PK = pharmacokinetics, how exposure changes over time. PD = pharmacodynamics, biological effects of the drug. A first dose is a starting point for learning; it is not the eventual optimized dose.'},
 people:{title:'A shared scientific argument.',lede:'In a biotech startup, an IND is usually prepared by a coordinated team, often with external specialists and service providers.',cards:[['Scientific contributors','Discovery and translational scientists, DMPK, toxicology, CMC, and clinical teams generate and interpret evidence in their areas.'],['Integration + preparation','A regulatory lead coordinates strategy and submission. Medical writers and regulatory publishing specialists may help turn the evidence into consistent documents.'],['Responsibility + use','The sponsor has regulatory responsibilities. Investigators use the protocol and investigator’s brochure to conduct the study; contracting work out is distinct from transferring obligations.']],question:'Where your expertise adds value',answer:'Connect a mechanistic concern to a testable question. Challenge species relevance, biomarker interpretation, and exposure assumptions. Explain what a study supports and where expert input is needed.',lens:'AI can help structure questions and compare documents. The team remains responsible for checking the evidence, sources, and conclusions.',source:6,terms:'This is a typical collaboration pattern, not a required organization chart. The investigator’s brochure (IB) synthesizes relevant information about the investigational product for investigators.'},
 review:{title:'Evidence, assembled and maintained.',lede:'The IND supports investigational use for proposed clinical studies. It is distinct from an application to market a drug.',cards:[['The content','Scientific summaries, nonclinical reports, CMC, protocols, an investigator’s brochure as applicable, administrative material, and prior human experience where relevant.'],['The organization','The electronic common technical document (eCTD) organizes regional material in Module 1, summaries in 2, quality in 3, nonclinical reports in 4, and clinical material in 5.'],['The continuing work','Review new information, amend protocols and other information as appropriate, and meet applicable safety and annual reporting obligations as development continues.']],question:'When can the first study start?',answer:'Under the US IND rule, the investigation may begin 30 days after FDA receipt unless a clinical hold applies, or earlier if FDA notifies the sponsor that it may begin. Institutional review board (IRB) approval and applicable consent and trial-readiness conditions also need to be met.',lens:'A submission is a versioned body of evidence. Technical acceptance of a file does not establish scientific adequacy or authorize a study by itself.',source:7,terms:'In the US eCTD, the IB is in Module 1 and clinical protocols are in Module 5. Initial INDs do not populate every section used later in development.'}
};
